  public function executeExportarMarc()
  {
  	$documentacion = DocumentacionPeer::retrieveByPk($this->getRequestParameter('documentacion_id'));
  	$manual_tecnico = ManualTecnicoPeer::retrieveByPk($this->getRequestParameter('manualtecnico_id'));
  	$cad = sprintf("%05d",$documentacion->getDocumentacionId()).'nam  ';
  	$cad .= '22'.sprintf("%05d",$manual_tecnico->getManualtecnicoId()).'a 4500008004100000';
  	$temp = substr($documentacion->getFechaCreacion(),0,10);
  	$cad .= str_replace("-",'',$temp);
  	$cad .= 's'.date("Y");
  	$cad .= '|||        '.$documentacion->getIdioma()->getCodigo();  	
  	$this->cad = $cad;
  } 
  
