  public function executeUpdate()
  {
    if (!$this->getRequestParameter('manualtecnico_id'))
    {
      $manual_tecnico = new ManualTecnico();
      $documentacion   = new Documentacion();
    }
    else
    {
      $documentacion = DocumentacionPeer::retrieveByPK($this->getRequestParameter('documentacion_id'));	
      $manual_tecnico = ManualTecnicoPeer::retrieveByPk($this->getRequestParameter('manualtecnico_id'));
      $this->forward404Unless($manual_tecnico);
    }
	
	//$documentacion->setDocumentacionId($this->getRequestParameter('documentacion_id'));
	$documentacion->setIdiomaId($this->getRequestParameter('idioma_id'));
	$documentacion->setEstadodocumentacionId(1);
	$documentacion->setTipodocumentacionId(1);//id del modulo de manual tecnico.	
	$documentacion->setTitulo($this->getRequestParameter('titulo'));
	$documentacion->setOtraInformacionTitulo($this->getRequestParameter('otra_informacion_titulo'));
	$documentacion->setPrimeraMencionResponsabilidad($this->getRequestParameter('primera_mencion_responsabilidad'));
	$documentacion->setMencionResponsabilidad($this->getRequestParameter('mencion_responsabilidad'));
	$documentacion->setNumeroClasificacion($this->getRequestParameter('numero_clasificacion'));
	$documentacion->setDescriptoresTematicos($this->getRequestParameter('descriptores_tematicos'));
	$documentacion->setCodigoBarras($this->getRequestParameter('codigo_barras'));
	$documentacion->setUbicacion($this->getRequestParameter('ubicacion'));
	if($this->getRequestParameter('manualtecnico_id')){
	   $documentacion->setFechaCreacion(date('Y-m-d G:i:s'));
	}
	$documentacion->setFechaModificacion(date('Y-m-d'));
	$documentacion->save();
	
    //$manual_tecnico->setManualtecnicoId($this->getRequestParameter('manualtecnico_id'));
    $manual_tecnico->setEspecialidadId($this->getRequestParameter('especialidad_id'));
    if($this->getRequestParameter('documentacion_id')){
    	$manual_tecnico->setDocumentacionId($this->getRequestParameter('documentacion_id'));
    }else{
		$manual_tecnico->setDocumentacionId($documentacion->getDocumentacionId());
	}
    //$manual_tecnico->setDocumentacionId($this->getRequestParameter('documentacion_id'));
    $manual_tecnico->setMencionEdicion($this->getRequestParameter('mencion_edicion'));
    $manual_tecnico->setVersion($this->getRequestParameter('version'));
    $manual_tecnico->setPaginacion($this->getRequestParameter('paginacion'));
    $manual_tecnico->setIlustraciones($this->getRequestParameter('ilustraciones', 0));
    $manual_tecnico->setVolumen($this->getRequestParameter('volumen'));
    $manual_tecnico->setMaterialComplemetario($this->getRequestParameter('material_complemetario'));
    $manual_tecnico->setIsbn($this->getRequestParameter('isbn'));
    $manual_tecnico->setNotasContenido($this->getRequestParameter('notas_contenido'));

    $manual_tecnico->save();       
    
    if($this->getRequestParameter('manualtecnico_id')){
	  $this->userEdit($this->getRequestParameter('idUser'),$documentacion->getDocumentacionId());
	  //$this->getUser()->userEdit($this->getRequestParameter('idUser'),$documentacion->getDocumentacionId());  	
	}else{
	  $this->userDoc($this->getRequestParameter('idUser'),$documentacion->getDocumentacionId());	
	  //$this->getUser()->userDoc($this->getRequestParameter('idUser'),$documentacion->getDocumentacionId());	
	}
	if($this->getRequestParameter('manualtecnico_id')){
		
	    return $this->redirect($this->getRequest()->getScriptName().'/documentacion_tecnica/show?documentacion_id='.$documentacion->getDocumentacionId());
	} 
    //return $this->redirect($this->getRequest()->getScriptName().'/manual_tecnico/show?documentacion_id='.$documentacion->getDocumentacionId().'&flag=1');
    return $this->redirect($this->getRequest()->getScriptName().'/documentacion_tecnica/list?tipo_documentacion_id=1');
  }
  
